pragma solidity ^0.8.19;

/**
 * @title TicTacToe
 * @author Based on a request for a simple Tic Tac Toe game.
 * @notice A very simple, single-game instance of Tic Tac Toe for two players.
 * This contract does not use OpenZeppelin contracts as its logic is self-contained
 * and does not require features like access control, pausable, or token standards.
 */
contract TicTacToe {
    // --- Enums ---

    /**
     * @dev Represents the state of the game.
     * NotStarted: The game is idle, waiting for players.
     * InProgress: The game is actively being played.
     * Finished: The game has concluded with a winner or a draw.
     */
    enum GameState {
        NotStarted,
        InProgress,
        Finished
    }

    /**
     * @dev Represents a piece on the board.
     * Empty: A cell that has not been played.
     * X: A cell occupied by Player X.
     * O: A cell occupied by Player O.
     */
    enum Piece {
        Empty, // 0
        X, // 1
        O  // 2
    }

    // --- State Variables ---

    address public playerX;
    address public playerO;
    address public currentPlayer;
    GameState public gameState;
    address public winner;
    uint8 public moveCount;

    // The 3x3 game board, represented as a flat array of 9 elements.
    Piece[9] public board;

    // --- Events ---

    event GameStarted(address indexed playerX, address indexed playerO);
    event MoveMade(address indexed player, uint8 row, uint8 col, Piece piece);
    event GameOver(address indexed winner, bool isDraw);

    /**
     * @notice Constructor is empty as required. The contract is initialized with default values.
     */
    constructor() {}

    /**
     * @notice Starts a new game instance.
     * @dev Can only be called when no game is currently in progress. The previous game's
     * state is cleared upon starting a new one. The caller (`msg.sender`) becomes Player X.
     * @param _playerO The address of the opponent, who will be Player O.
     */
    function startGame(address _playerO) external {
        require(gameState != GameState.InProgress, "A game is already in progress.");
        require(_playerO != address(0), "Player O cannot be the zero address.");
        require(msg.sender != _playerO, "Players cannot be the same address.");

        // Reset and initialize game state
        for (uint8 i = 0; i < 9; i++) {
            board[i] = Piece.Empty;
        }

        playerX = msg.sender;
        playerO = _playerO;
        currentPlayer = playerX; // Player X always starts
        gameState = GameState.InProgress;
        winner = address(0);
        moveCount = 0;

        emit GameStarted(playerX, playerO);
    }

    /**
     * @notice Allows the current player to make a move on the board.
     * @param row The row to place the piece (0, 1, or 2).
     * @param col The column to place the piece (0, 1, or 2).
     */
    function makeMove(uint8 row, uint8 col) external {
        require(gameState == GameState.InProgress, "Game is not in progress.");
        require(msg.sender == currentPlayer, "Not your turn.");
        require(row < 3 && col < 3, "Move is out of bounds.");

        uint8 index = row * 3 + col;
        require(board[index] == Piece.Empty, "Cell is already taken.");

        Piece currentPiece = (currentPlayer == playerX) ? Piece.X : Piece.O;
        board[index] = currentPiece;
        moveCount++;

        emit MoveMade(msg.sender, row, col, currentPiece);

        // Check for win or draw
        if (_checkWin(currentPiece)) {
            _endGame(currentPlayer, false);
        } else if (moveCount == 9) {
            _endGame(address(0), true); // Draw
        } else {
            // Switch turn to the other player
            currentPlayer = (currentPlayer == playerX) ? playerO : playerX;
        }
    }

    /**
     * @notice Internal function to check if the last move resulted in a win.
     * @param _piece The piece (X or O) of the player who just moved.
     * @return A boolean indicating if the player has won.
     */
    function _checkWin(Piece _piece) internal view returns (bool) {
        // Winning combinations: 3 rows, 3 columns, 2 diagonals
        // Check rows
        for (uint8 i = 0; i < 3; i++) {
            if (board[i * 3] == _piece && board[i * 3 + 1] == _piece && board[i * 3 + 2] == _piece) {
                return true;
            }
        }

        // Check columns
        for (uint8 i = 0; i < 3; i++) {
            if (board[i] == _piece && board[i + 3] == _piece && board[i + 6] == _piece) {
                return true;
            }
        }

        // Check diagonals
        if (board[0] == _piece && board[4] == _piece && board[8] == _piece) {
            return true;
        }
        if (board[2] == _piece && board[4] == _piece && board[6] == _piece) {
            return true;
        }

        return false;
    }

    /**
     * @notice Internal function to end the game and set the final state.
     * @param _winner The address of the winning player, or address(0) for a draw.
     * @param _isDraw A boolean indicating if the game was a draw.
     */
    function _endGame(address _winner, bool _isDraw) internal {
        gameState = GameState.Finished;
        winner = _winner;
        emit GameOver(_winner, _isDraw);
    }

    /**
     * @notice A view function to get the current board state.
     * @return The 9-element array representing the board.
     */
    function getBoard() external view returns (Piece[9] memory) {
        return board;
    }
}

